// Synthetic, in-memory acceptance only: this does not attest statutory sources or release money.
import assert from 'node:assert/strict';
import {manageProductionEvidence} from '../../app/lib/production-evidence.ts';
import {manageProductionPayrollPolicy} from '../../app/lib/production-payroll-policy.ts';
import {prepareProductionPayroll,decideProductionPayroll,exportProductionPayrollCsv,readProductionPayroll} from '../../app/lib/production-payroll.ts';
import {operateProduction} from '../../app/lib/production-operations.ts';
import {ZA_2027_SARS_POLICY_CANDIDATE} from '../../app/lib/payroll-engine.ts';
export const freshHeaders=actor=>new Headers({'x-lokd-verified-mfa-enrolled':'true','x-lokd-verified-user-id':actor.userId,'x-lokd-verified-second-factor-at':new Date().toISOString()});
export async function consumeConnectedPayroll({db,database,officerId,shiftId,maker,checker,applicant,client}){
 const finance={userId:'connected-finance',email:'connected-finance@example.test',operations:true,owner:false};
 for(const [actor,roles] of [[maker,['payroll_preparer','payroll_reviewer']],[checker,['payroll_reviewer']],[finance,['finance_approver']]])for(const role of roles)await operateProduction(db,checker,{action:'grant_operator',email:actor.email,role,limitCents:10000000},freshHeaders(checker));
 const t=database.prepare('SELECT * FROM shift_timesheets WHERE shift_id=?').get(shiftId);
 assert.ok(t.recorded_minutes>0);assert.equal(t.payable_minutes,t.recorded_minutes);
 const rules={...ZA_2027_SARS_POLICY_CANDIDATE,version:'isolated-connected-period-v1',effectiveFrom:t.service_date,effectiveTo:t.service_date,payPeriodsPerYear:365,privateSecuritySector:{...ZA_2027_SARS_POLICY_CANDIDATE.privateSecuritySector,healthCoverTreatmentStatus:'source_verified'}};
 const preparedPolicy=await manageProductionPayrollPolicy(db,maker,{action:'prepare_payroll_policy',rules,sourcesReviewed:true,sourceReference:'Isolated connected fixture only; no live statutory acceptance.'},freshHeaders(maker));
 const policy=()=>database.prepare('SELECT * FROM payroll_policy_versions WHERE id=?').get(preparedPolicy.policyId);
 for(const [actor,action] of [[checker,'review_payroll_policy'],[finance,'activate_payroll_policy']])await manageProductionPayrollPolicy(db,actor,{action,policyId:policy().id,version:policy().version,policyHash:policy().policy_hash,sourcesReviewed:true,reason:'Independent synthetic fixture review, not genuine source acceptance.'},freshHeaders(actor));
 const input={action:'prepare_payroll_period',requestKey:'connected-payroll',employerId:t.employer_id,periodStart:t.service_date,periodEnd:t.service_date,payDate:t.service_date,policyId:policy().id,employerAnnualPayrollCents:100000000,completePeriodReviewed:true,officerInputs:[{officerId,ageAtTaxYearEnd:30,medicalSchemeMembers:0,deductibleRetirementContributionCents:0,employeeHealthCoverCents:0,otherLawfulDeductionCents:0,monthlyBasicCents:2000000,wageArea:'areas_one_and_two',sourceReference:'Isolated connected payroll facts only',lawfulDeductionsReviewed:true}]};
 await assert.rejects(prepareProductionPayroll(db,maker,input,freshHeaders(maker)),/payroll calculation profile/);
 const profile=await manageProductionEvidence(db,maker,{action:'prepare_evidence',kind:'payroll_profile',sourceDocumentsReviewed:true,expiresAt:new Date(Date.now()+86400000).toISOString(),fields:{profileId:'CONNECTED-PAYROLL-PROFILE',officerId,engagementId:t.workforce_engagement_id,employerId:t.employer_id,taxToken:'vault:fixture:tax',uifToken:'vault:fixture:uif',providentToken:'vault:fixture:provident',payrollReference:'Isolated connected profile sources'}});
 await manageProductionEvidence(db,checker,{action:'decide_evidence',reviewId:profile.reviewId,decision:'approve',evidenceIndependentlyChecked:true,reason:'Independent synthetic payroll profile review'});
 const prepared=await prepareProductionPayroll(db,maker,input,freshHeaders(maker));assert.equal(prepared.paymentReleased,false);
 assert.equal((await prepareProductionPayroll(db,maker,input,freshHeaders(maker))).alreadyPrepared,true);
 await assert.rejects(prepareProductionPayroll(db,maker,{...input,requestKey:'connected-duplicate'},freshHeaders(maker)),/unallocated/);
 const source=database.prepare('SELECT * FROM pay_item_sources WHERE timesheet_id=?').get(t.id);
 assert.equal(source.timesheet_version,t.version);assert.equal(source.active_key,t.id);assert.equal(source.payable_minutes,t.payable_minutes);assert.equal(source.gross_wage_cents,t.gross_wage_cents);
 assert.equal(database.prepare('SELECT count(*) AS n FROM pay_item_sources WHERE timesheet_id=?').get(t.id).n,1);
 const snapshot=database.prepare('SELECT * FROM production_payroll_snapshots WHERE run_id=?').get(prepared.runId),item=JSON.parse(snapshot.payload_json).items[0];
 assert.equal(JSON.parse(snapshot.payload_json).calendar,'Africa/Johannesburg');assert.equal(item.officerId,officerId);assert.equal(item.engagementId,t.workforce_engagement_id);assert.equal(item.sources[0].id,t.id);assert.equal(item.calculation.grossCents,t.gross_wage_cents);assert.equal(item.calculation.earnings[0].minutes,t.payable_minutes);
 const run=()=>database.prepare('SELECT * FROM payroll_runs WHERE id=?').get(prepared.runId);
 const command=action=>({action,runId:prepared.runId,version:run().version,calculationHash:snapshot.payload_hash,calculationReviewed:true,note:'Independent synthetic payroll calculation inspection'});
 await assert.rejects(decideProductionPayroll(db,maker,command('first_approve_payroll'),freshHeaders(maker)),/maker/);
 const first=command('first_approve_payroll');await decideProductionPayroll(db,checker,first,freshHeaders(checker));await assert.rejects(decideProductionPayroll(db,checker,first,freshHeaders(checker)),/changed/);
 await assert.rejects(decideProductionPayroll(db,checker,command('second_approve_payroll'),freshHeaders(checker)),/finance approver|independent/);
 for(const [actor,action] of [[finance,'second_approve_payroll'],[maker,'export_payroll']])assert.equal((await decideProductionPayroll(db,actor,command(action),freshHeaders(actor))).paymentReleased,false);
 const csv=await exportProductionPayrollCsv(db,maker,prepared.runId,freshHeaders(maker));assert.match(csv,/NOT_RELEASED/);assert.ok(!csv.includes('vault:fixture'));assert.equal(run().status,'exported');assert.equal(run().settlement_reference,null);
 assert.equal((await readProductionPayroll(db,applicant)).payrollItems.length,1);assert.equal((await readProductionPayroll(db,client)).payrollItems.length,0);
 for(const table of ['disbursement_batches','employee_payment_instructions','partner_payment_instructions'])assert.equal(database.prepare(`SELECT count(*) AS n FROM ${table}`).get().n,0,table);
 assert.throws(()=>database.prepare("UPDATE payroll_runs SET status='paid',version=version+1 WHERE id=?").run(prepared.runId),/payroll|decision/);
 const {financeDocumentJourney}=await import('./finance-document-journey.mjs');
 const document=await financeDocumentJourney({db,database,maker,finance,recipient:applicant,kind:'payslip',sourceId:item.id,headers:freshHeaders(finance)});
 assert.equal((await document.read()).documents[0].currentState,'unpaid');
 return {runId:prepared.runId,input,document};
}
